import re

# IUPAC map
iupac = {
    "A": "A", "C": "C", "G": "G", "T": "T",
    "R": "[AG]", "Y": "[CT]", "S": "[GC]", "W": "[AT]",
    "K": "[GT]", "M": "[AC]", "B": "[CGT]", "D": "[AGT]",
    "H": "[ACT]", "V": "[ACG]", "N": "[ACGT]"
}
def to_regex(seq):
    return "".join(iupac.get(b, b) for b in seq)

p_515f = to_regex("GTGYCAGCMGCCGCGGTAA")
p_806r = to_regex("GGACTACNVGGGTWTCTAAT")

